import subprocess as s,sys
bad=[]
for sc in ('research-none','research-partial'):
    for co in ('shared','isolated'):
        p=s.run([sys.executable,'_tools/benchmarks.py','multi','run',sc,'--dry-run','--coord',co],capture_output=True,text=True,timeout=600)
        areas=[l.rpartition('area ')[2].strip() for l in p.stdout.splitlines() if l.startswith('agent ') and ' area ' in l]
        print(sc,co,p.returncode,areas,p.stderr[-200:])
        if p.returncode!=0 or len(areas)<3 or (sc=='research-none' and len(set(areas))!=len(areas)) or (sc=='research-partial' and len(set(areas))<2):
            bad.append((sc,co))
print('not runnable:',bad);sys.exit(1 if bad else 0)

import collections,csv,sys
SIZED=4
c=collections.defaultdict(set)
for r in csv.DictReader(open('kb/_self/reports/benchmarks.csv',encoding='utf-8')):
    if r['scenario']=='multi' and r['date']>='2026-10-26' and r['case'] in ('research','research-none','research-partial') and 'delta' not in r['arm']:
        for w in r['arm'].split():
            if w in ('coord=shared','coord=isolated'):
                c[(r['case'],w)].add(r['record'])
want=[(k,a) for k in ('research-none','research-partial','research') for a in ('coord=shared','coord=isolated')]
short={'%s %s'%x:len(c[x]) for x in want if len(c[x])<SIZED}
print('records per level and arm since 2026-10-26:',{'%s %s'%x:len(c[x]) for x in want},'short of',SIZED,':',short)
sys.exit(1 if short else 0)
